const express = require('express');
const app = express();

// Get server start time for uptime calculation
const serverStartTime = Date.now();

// Get version from package.json or environment, default to '1.0.0'
const getVersion = () => {
  try {
    return require('./package.json').version || '1.0.0';
  } catch (e) {
    return process.env.npm_package_version || '1.0.0';
  }
};

// Check if required environment variables are set
const checkEnvVars = () => {
  const requiredVars = ['DATABASE_URL', 'SECRET_KEY']; // Example required variables
  return requiredVars.every(varName => process.env[varName]);
};

app.get('/health', (req, res) => {
  const uptimeMs = Date.now() - serverStartTime;
  const uptime = {
    seconds: Math.floor(uptimeMs / 1000),
    minutes: Math.floor(uptimeMs / 60000),
    hours: Math.floor(uptimeMs / 3600000),
    days: Math.floor(uptimeMs / 86400000)
  };

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: getVersion(),
    uptime 
  });
});

app.get('/ready', (req, res) => {
  if (checkEnvVars()) {
    res.json({ status: 'ready', timestamp: new Date().toISOString() });
  } else {
    res.status(503).json({ 
      status: 'not_ready', 
      message: 'Missing required environment variables',
      timestamp: new Date().toISOString() 
    });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
  console.log(`Version: ${getVersion()}`);
});

module.exports = app;

